// TypeScript Version: 4.1

/**
* Tests if a JSON Pointer resolves to a value in a document.
*
* ## Notes
*
* -   Implements pointer resolution check per RFC 6901.
* -   Returns `true` if the pointer resolves to an existing property or array element; otherwise `false`.
* -   An empty string pointer refers to the root of the document and returns `true` for any valid object or array.
* -   The `-` token on an array references the position after the last element (nonexistent element), so it returns `false`.
*
* @param document - JSON document
* @param pointer - JSON Pointer string
* @returns boolean indicating if pointer resolves
*
* @example
* var bool = has( { 'foo': [ 'bar', 'baz' ] }, '/foo/0' );
* // returns true
*
* @example
* var bool = has( { 'foo': 'bar' }, '/foo' );
* // returns true
*
* @example
* var bool = has( { 'foo': 'bar' }, '/missing' );
* // returns false
*
* @example
* var bool = has( { 'foo': 'bar' }, '' );
* // returns true
*/
declare function has( document: Record<string, any> | Array<any>, pointer: string ): boolean;


// EXPORTS //

export = has;
